package com.salespunch360.mobile

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.salespunch360.mobile.account.*
import com.salespunch360.mobile.data.*
import java.io.IOException
import kotlinx.coroutines.Job
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch
import kotlinx.serialization.json.*

class AccountSalesViewModel(app:Application):AndroidViewModel(app){private val session=SecureSession(app);private val api=ApiClient(session);private val amendments=SaleAmendmentClient(session);private val _state=MutableStateFlow(AccountSalesState());val state:StateFlow<AccountSalesState> = _state;private var searchJob:Job?=null;private val creationIdentity=CommercialCreationIdentity()
 init{refresh()}
 fun refresh(){searchJob?.cancel();searchJob=viewModelScope.launch{_state.value=_state.value.copy(loading=true,error=null);try{val raw=api.accountSalesOptions();val options=SalesOptions(customerPrices=raw.array("customerPrices"),updateSalePrice=raw["canUpdateSalePrices"]?.jsonPrimitive?.booleanOrNull==true&&((raw["accountSettings"] as? JsonObject)?.get("itemSettings") as? JsonObject)?.get("updateSalePrice")?.jsonPrimitive?.booleanOrNull==true,wholesalePrice=((raw["accountSettings"] as? JsonObject)?.get("itemSettings") as? JsonObject)?.get("wholesalePrice")?.jsonPrimitive?.booleanOrNull!=false,itemWiseDiscount=((raw["accountSettings"] as? JsonObject)?.get("itemSettings") as? JsonObject)?.get("itemWiseDiscount")?.jsonPrimitive?.booleanOrNull!=false,invoiceCustomFields=raw.array("invoiceCustomFields"),batches=raw.array("batches"),serials=raw.array("serials"),customerAdvances=raw.array("customerAdvances"),defaultStateCode=(raw["accountSettings"] as? JsonObject)?.str("defaultStateCode").orEmpty(),recentSalePrices=raw.array("recentSalePrices"),transactionDefaults=(raw["accountSettings"] as? JsonObject)?.get("transactionDefaults") as? JsonObject?:JsonObject(emptyMap()),types=raw["allowedDocumentTypes"]?.jsonArray?.map{it.jsonPrimitive.content}.orEmpty(),branches=raw.array("branches").map{it.option()},customers=raw.array("customers").map{it.option()},products=raw.array("products").map{it.option()},services=raw.array("services").map{it.option("sellingRate")},workPackages=raw.array("workPackages").map{it.option("sellingRate")},warehouses=raw.array("warehouses").map{it.option()},projects=raw.array("projects").map{it.option()},units=raw.array("units").map{it.option()},sourceDocuments=raw.array("sourceDocuments"),numberingSeries=raw.array("numberingSeries").map{NumberingPreview(it.str("branchId"),it.str("prefix"),it.str("suffix"),it.str("padding").toIntOrNull()?:2,it.str("nextSequence").toLongOrNull()?:1)});val rows=loadRows();_state.value=_state.value.copy(loading=false,options=options,rows=rows)}catch(e:Exception){_state.value=_state.value.copy(loading=false,error=errorText(e))}}}
 fun search(value:String){_state.value=_state.value.copy(query=value);reloadRows()};fun filter(type:String?){_state.value=_state.value.copy(typeFilter=type);reloadRows()}
 private fun reloadRows(){searchJob?.cancel();searchJob=viewModelScope.launch{_state.value=_state.value.copy(loading=true);try{_state.value=_state.value.copy(loading=false,rows=loadRows())}catch(e:Exception){_state.value=_state.value.copy(loading=false,error=errorText(e))}}}
 private suspend fun loadRows()=api.accountSalesDocuments(_state.value.typeFilter,_state.value.query).map{it.jsonObject}.map{SalesDocumentRow(it.str("id"),it.str("type"),it.str("documentNumber"),it.str("partyName"),it.str("issueDate").take(10),it.str("status"),it.str("grandTotal"),it.str("outstanding"),it.str("paymentStatus"))}
 fun newDocument(type:String,projectId:String?=null,projectMode:Boolean=false){if(_state.value.saving)return;val o=_state.value.options;if(type !in o.types)return;val required=projectMode||!projectId.isNullOrBlank();if(required&&o.projects.isEmpty()){_state.value=_state.value.copy(error="Projects are unavailable for this account.");return};val initial=o.defaultSalesDraft(type,o.branches.firstOrNull()?.id.orEmpty(),required);val selected=if(projectId.isNullOrBlank())initial else selectProjectForInvoice(initial,o,projectId);if(selected==null){_state.value=_state.value.copy(error="This Project or its customer is unavailable.");return};creationIdentity.reset();_state.value=_state.value.copy(editor=selected,detail=null,error=null,message=null)}
 fun updateInvoicePrefix(prefix:String){val draft=_state.value.editor?:return;viewModelScope.launch{_state.value=_state.value.copy(saving=true,error=null);runCatching{api.saveSalesInvoicePrefix(draft.branchId,prefix)}.onSuccess{row->val preview=NumberingPreview(row.str("branchId"),row.str("prefix"),row.str("suffix"),row.str("padding").toIntOrNull()?:2,row.str("nextSequence").toLongOrNull()?:1);_state.value=_state.value.copy(saving=false,options=_state.value.options.copy(numberingSeries=_state.value.options.numberingSeries.filterNot{it.branchId==draft.branchId}+preview),message="Invoice prefix saved.")}.onFailure{_state.value=_state.value.copy(saving=false,error=errorText(it as Exception))}}}
 fun createSaleCustomer(fields:JsonObject,done:(String)->Unit){val draft=_state.value.editor?:return;viewModelScope.launch{_state.value=_state.value.copy(saving=true,error=null);runCatching{api.saveAccountMaster("customers",null,buildJsonObject{put("branchId",draft.branchId);fields.forEach{(key,value)->put(key,value)}})}.onSuccess{customer->_state.value=applyCreatedSaleCustomer(_state.value,SalesOption(customer.id,customer.name,customer.branchId,phone=customer.phone));done(customer.id);refresh()}.onFailure{_state.value=_state.value.copy(saving=false,error=errorText(it as Exception))}}}
 fun editDraft(value:SalesEditorDraft){if(_state.value.saving)return;_state.value=_state.value.copy(editor=value)};fun closeEditor(){if(_state.value.saving)return;_state.value=_state.value.copy(editor=null)}
 fun addLine(){_state.value.editor?.let{editDraft(it.copy(lines=it.lines+SalesLineDraft()))}};fun updateLine(index:Int,line:SalesLineDraft){_state.value.editor?.let{editDraft(it.copy(lines=it.lines.mapIndexed{i,x->if(i==index)line else x}))}};fun removeLine(index:Int){_state.value.editor?.let{if(it.lines.size>1)editDraft(it.copy(lines=it.lines.filterIndexed{i,_->i!=index}))}}

 fun save(saveAndNew:Boolean=false){if(_state.value.saving)return;val draft=_state.value.editor?:return;if(draft.projectRequired&&(draft.projectId.isBlank()||selectProjectForInvoice(draft,_state.value.options,draft.projectId)?.customerId!=draft.customerId)){_state.value=_state.value.copy(error="Select an available Project and its linked customer.");return};_state.value=_state.value.copy(saving=true,error=null);viewModelScope.launch{try{val raw=salesDraftPayload(draft);val body=creationIdentity.payload(raw);val created=if(draft.editingSourceId.isNotBlank())amendments.replace(draft.editingSourceId,body) else api.createAccountSalesDocument(body);creationIdentity.reset();val submitted=draft.type=="SALES_INVOICE";if(submitted&&_state.value.options.updateSalePrice)_state.value=_state.value.copy(salePriceDocumentId=created.str("id"));if(saveAndNew&&draft.editingSourceId.isBlank()){_state.value=_state.value.copy(saving=false,editor=_state.value.options.defaultSalesDraft(draft.type,draft.branchId,draft.projectRequired).copy(projectId=draft.projectId,customerId=if(draft.projectRequired)draft.customerId else ""),detail=null,message=if(submitted)"Sale submitted. Ready for a new sale." else "Document saved. Ready for a new document.")}else{val detail=runCatching{api.accountSalesDocument(created.str("id"))}.getOrDefault(created);val display=buildJsonObject{detail.forEach{(key,value)->put(key,value)};put("previewOnOpen",submitted&&draft.editingSourceId.isBlank()&&_state.value.options.transactionPreference("invoicePreview",true))};_state.value=_state.value.copy(saving=false,editor=null,detail=display,message=if(draft.editingSourceId.isNotBlank())"Sale updated successfully." else if(submitted)"Sale submitted successfully." else "Document saved.");if(created["lines"] !is JsonArray)open(created.str("id"))};refresh()}catch(e:Exception){_state.value=_state.value.copy(saving=false,error=errorText(e))}}}
 fun closePriceConfirmation(){_state.value=_state.value.copy(salePriceDocumentId=null);refresh()}
 fun open(id:String)=viewModelScope.launch{_state.value=_state.value.copy(loading=true,error=null);try{_state.value=_state.value.copy(loading=false,detail=api.accountSalesDocument(id))}catch(e:Exception){_state.value=_state.value.copy(loading=false,error=errorText(e))}};fun closeDetail(){_state.value=_state.value.copy(detail=null)}
 fun duplicateSale(id:String){
  if(_state.value.saving||_state.value.loading)return
  val options=_state.value.options
  if("SALES_INVOICE" !in options.types){_state.value=_state.value.copy(error="You do not have permission to create Sale invoices.");return}
  _state.value=_state.value.copy(loading=true,detail=null,editor=null,error=null,message=null)
  viewModelScope.launch{try{
   val draft=duplicateSavedSaleDraft(api.accountSalesDocument(id))
   if(options.branches.none{it.id==draft.branchId})throw IllegalArgumentException("This branch is unavailable.")
   val selected=if(draft.projectId.isBlank())draft else selectProjectForInvoice(draft,options,draft.projectId)?.takeIf{it.customerId==draft.customerId}?:draft.copy(projectId="",projectRequired=false)
   creationIdentity.reset();_state.value=_state.value.copy(loading=false,editor=selected,detail=null,error=null,message="New copy ready. Review and save to create a new invoice.")
  }catch(error:kotlinx.coroutines.CancellationException){throw error}catch(error:Exception){_state.value=_state.value.copy(loading=false,error=errorText(error))}}
 }
 fun editSavedSale(){val doc=_state.value.detail?:return;if(doc.str("type")!="SALES_INVOICE"||doc.str("status")!="POSTED")return;if((doc["paymentSummary"] as? JsonObject)?.bool("canChange")!=true)return;creationIdentity.reset();_state.value=_state.value.copy(detail=null,editor=savedSaleEditorDraft(doc))}
 fun deleteSavedSale(){val doc=_state.value.detail?:return;viewModelScope.launch{_state.value=_state.value.copy(saving=true,error=null);try{amendments.delete(doc.str("id"));_state.value=_state.value.copy(saving=false,detail=null,message="Sale deleted with accounting and stock reversal.");refresh()}catch(e:Exception){_state.value=_state.value.copy(saving=false,error=errorText(e))}}}
 fun requestPost(id:String){_state.value=_state.value.copy(postingId=id)};fun cancelPost(){_state.value=_state.value.copy(postingId=null)};fun confirmPost(){val id=_state.value.postingId?:return;viewModelScope.launch{_state.value=_state.value.copy(saving=true,postingId=null);try{api.postAccountSalesDocument(id);_state.value=_state.value.copy(saving=false,detail=api.accountSalesDocument(id),message="Document posted successfully.");refresh()}catch(e:Exception){_state.value=_state.value.copy(saving=false,error=errorText(e))}}}
 private fun errorText(e:Exception)=when{e is IOException->"Connection interrupted. Your inputs were kept; retry the same request when online.";e is ApiException&&e.status==403->"You are not authorized for this action.";e is ApiException&&e.code?.contains("SALE_HAS_PAYMENTS_OR_ADJUSTMENTS")==true->"This Sale has a payment or adjustment. Reverse that first before Edit/Delete.";e is ApiException&&e.code=="INVALID_INPUT"->"Check the document fields and line items.";else->"The server could not complete this Account action."}
}
